/* All explanatory figures consume saved, computed SHAP arrays. No synthetic results. */
'use strict';
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={
 grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
 database:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0"/>',
 layers:'<path d="m12 3 10 5-10 5L2 8l10-5Zm-10 9 10 5 10-5M2 17l10 5 10-5"/>',
 chart:'<path d="M4 3v17h17M8 16v-5m5 5V7m5 9V4"/>',
 leaf:'<path d="M20 3C8 2 2 8 6 15s15 3 14-12ZM4 21l12-13"/>',
 file:'<path d="M14 2H5v20h14V7l-5-5ZM14 2v6h5M8 12h8m-8 4h8"/>',
 upload:'<path d="M12 16V3m-5 5 5-5 5 5M3 15v6h18v-6"/>',
 download:'<path d="M12 3v13m-5-5 5 5 5-5M3 17v4h18v-4"/>',
 arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
 play:'<path d="m7 3 14 9-14 9V3Z"/>',
 check:'<path d="m4 12 5 5L20 6"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 10v7m0-11v1"/>',
 bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-8l1-7Z"/>',
 battery:'<rect x="2" y="6" width="18" height="13" rx="2"/><path d="M23 10v5M7 10v5m4-5v5m4-5v5"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 3"/>',
 settings:'<path d="M4 7h16M4 17h16"/><circle cx="8" cy="7" r="3"/><circle cx="16" cy="17" r="3"/>'
};
const icon=(name)=>'<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(icons[name]||icons.file)+'</svg>';
$$('[data-icon]').forEach(x=>x.innerHTML=icon(x.dataset.icon));
const titles={home:'工作台',data:'数据集与规划边界',plans:'规划方案对比',economy:'经济性分析',carbon:'低碳性分析',reports:'运行记录与报告'};
const S={catalog:null,datasets:[],ds:null,info:null,mapping:{},result:null,runs:[],job:null,page:'home',globalTab:'bar',localTab:'waterfall',cohort:'test',sample:0,dep:0,color:1,carbonTarget:'Cost_car',dataTab:'mapping'};
const fmt=(x,d=2)=>x==null?'—':Number(x).toLocaleString('zh-CN',{maximumFractionDigits:d});
const compact=x=>x==null?'—':Math.abs(x)>=1e8?fmt(x/1e8)+' 亿':Math.abs(x)>=1e4?fmt(x/1e4)+' 万':fmt(x);
const localTime=x=>new Date(x).toLocaleString('zh-CN',{hour12:false});
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),6000);}
async function api(path,options={}){if(!window.storageCloudApi)throw Error('浏览器工作区尚未就绪，请刷新网页。');return window.storageCloudApi(path,options);}
const post=(path,data)=>api(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});
const button=(label,action,primary=false,ico='')=>'<button class="'+(primary?'primary':'')+'" data-action="'+action+'">'+(ico?icon(ico):'')+label+'</button>';
const head=(eyebrow,title,desc,actions='')=>'<div class="page-head"><div><div class="eyebrow">'+eyebrow+'</div><h1>'+title+'</h1><p class="subtitle">'+desc+'</p></div><div class="actions">'+actions+'</div></div>';
const stat=(label,value,note='',color='',ico='')=>'<div class="card stat"><div class="stat-label">'+label+'<span class="stat-icon">'+(ico?icon(ico):'')+'</span></div><div class="stat-value '+color+'">'+value+'</div><div class="stat-note">'+note+'</div></div>';
const notice=(text,kind='')=>'<div class="notice '+kind+'">'+icon('info')+'<div>'+text+'</div></div>';
function empty(title,desc,action='data'){return '<div class="card empty">'+icon('layers')+'<h3>'+title+'</h3><p>'+desc+'</p><div class="actions">'+button(action==='data'?'前往数据工作区':'运行案例分析',action==='data'?'goto-data':'run',true,'arrow')+'</div></div>';}
function chart(id,cls=''){return '<div id="'+id+'" class="chart '+cls+'"></div>';}
function options(items,current){return items.map(x=>{let k=typeof x==='object'?x.key:x,label=typeof x==='object'?x.label:x;return '<option value="'+esc(k)+'"'+(String(k)===String(current)?' selected':'')+'>'+esc(label)+'</option>';}).join('');}
const activeTarget=()=>S.page==='carbon'?S.carbonTarget:'Cost_sum';
const indices=()=>S.result?(S.cohort==='test'?S.result.test_indices:S.result.rows.map((_,i)=>i)):[];
const rank=(key)=>{let t=S.result.targets[key],im=S.cohort==='test'?t.importance_test:t.importance_all;return im.map((v,j)=>({j,v})).sort((a,b)=>b.v-a.v).map(z=>z.j);};
function targetScale(key){const t=S.result.targets[key],m=t.actual.reduce((a,b)=>a+Math.abs(b),0)/t.actual.length;let scale=m>=1e8?1e8:m>=1e6?1e6:m>=1e4?1e4:1;return {scale,unit:t.unit+(scale===1?'':' ×10'+({1e8:'⁸',1e6:'⁶',1e4:'⁴'}[scale]))};}
function pbase(extra={}){return {paper_bgcolor:'transparent',plot_bgcolor:'transparent',font:{family:'Microsoft YaHei, sans-serif',color:'#50637d',size:11},margin:{l:250,r:34,t:24,b:56},colorway:['#2863d5','#12978d','#e55d84','#89b3ee'],xaxis:{gridcolor:'#edf1f7',zerolinecolor:'#9eb3d3',linecolor:'#dce4ef',tickfont:{size:10},automargin:true},yaxis:{gridcolor:'#edf1f7',tickfont:{size:11},automargin:true},hoverlabel:{bgcolor:'#fff',font:{family:'Microsoft YaHei',size:11}},...extra};}
function plot(id,traces,layout={}){const el=document.getElementById(id);if(!el)return;return Plotly.newPlot(el,traces,pbase(layout),{responsive:true,displaylogo:false,modeBarButtonsToRemove:['lasso2d','select2d'],toImageButtonOptions:{format:'png',filename:'储能规划-SHAP-'+id,scale:2}});}
function resizeCharts(){for(const e of $$('.js-plotly-plot'))Plotly.Plots.resize(e);}
async function selectDataset(id,sheet){S.ds=S.datasets.find(d=>d.id===id);if(!S.ds)return;S.info=await api('/api/datasets/'+id+'/inspect?sheet='+encodeURIComponent(sheet||S.ds.default_sheet));S.mapping={...S.info.mapping};workspacePrefs.setItem('public-storage-shap-dataset',id);}
async function loadResult(id){S.result=await api('/api/runs/'+id);if(S.result.dataset_id)await selectDataset(S.result.dataset_id,S.result.sheet);S.mapping={...S.result.config.mapping};S.sample=S.result.test_indices[0];S.dep=rank('Cost_sum')[0];S.color=rank('Cost_sum')[1]||0;S.carbonTarget='Cost_car';workspacePrefs.setItem('public-storage-shap-run',id);}
async function render(){const pg=(location.hash.slice(1)||'data');S.page=titles[pg]?pg:'home';$('#breadcrumb').textContent=titles[S.page];$$('[data-nav]').forEach(x=>x.classList.toggle('active',x.dataset.nav===S.page));const main=$('#main');switch(S.page){case'home':renderHome(main);break;case'data':renderData(main);break;case'plans':renderPlans(main);break;case'economy':case'carbon':renderAnalysis(main);break;case'reports':renderReports(main);break;} }
function renderHome(m){
 const r=S.result,info=S.info;
 m.innerHTML='<div class="hero"><div class="hero-copy"><div class="eyebrow">MULTI-TIMESCALE STORAGE / EXPLAINABLE PLANNING</div><h1>多时间尺度储能<br>协同规划可解释分析</h1><p class="subtitle">连接规划输入与方案结果，从经济性、低碳性两个维度，识别关键影响因素，追溯每一个方案的预测贡献。</p><div class="actions">'+button('打开案例数据','goto-data',true,'database')+button(r?'查看经济性解释':'运行案例分析',r?'goto-economy':'run',false,'arrow')+'</div></div><div class="hero-art"><div class="energy-unit">'+icon('battery')+'<b>短时储能</b><span>功率与能量容量</span></div><div class="art-link"></div><div class="energy-unit long">'+icon('layers')+'<b>长时储能</b><span>充放电与能量容量</span></div></div></div>'+
 '<div class="grid four section-gap">'+stat('有效案例记录',fmt(r?r.rows.length:info?.rows,0),esc(S.ds?.name||'等待导入'),'','database')+stat('本次可解释输入',((r?r.features.length:info?.feature_count)||0)+'<small>/ 14 项</small>','缺失参数在数据工作区单独列明','blue','settings')+stat('规划输出字段',(info?.output_count||0)+'<small>/ 10 项</small>','覆盖短时、长时储能与电源配置','','layers')+stat('分析维度','2<small>个核心维度</small>','规划总成本 / 规划环境成本','teal','chart')+'</div>'+
 '<div class="card section-gap"><div class="flow">'+[['01','导入与校验','输入边界与规划结果'],['02','拟合与评估','训练与独立测试'],['03','SHAP解释','全局规律与局部贡献'],['04','保存与导出','图表、矩阵与报告']].map(a=>'<div class="flow-step"><div class="flow-no">'+a[0]+'</div><div><b>'+a[1]+'</b><span>'+a[2]+'</span></div></div>').join('')+'</div></div>'+
 '<div class="grid two section-gap"><div class="card"><div class="card-head"><div><h2>当前案例</h2><p>原始规划数据保留，分析记录可追溯</p></div><span class="tag blue">当前数据案例</span></div><div class="card-body"><h3>'+esc(S.ds?.name||'尚未选择数据集')+'</h3><div class="metric-row"><span>当前工作表</span><b>'+esc(info?.sheet||'—')+'</b></div><div class="metric-row"><span>数据覆盖</span><b>'+(info?.feature_count||0)+'项输入 / '+(info?.output_count||0)+'项输出</b></div><div class="metric-row"><span>当前分析</span><b>'+(r?esc(r.config.model)+' / '+esc(localTime(r.created_at)):'尚未运行')+'</b></div>'+notice('当前数据提供'+(info?.feature_count||0)+'项输入与'+(info?.output_count||0)+'项规划结果。缺失输入不参与影响排序；储能规划结果可在方案页对比。',(info?.feature_count||0)<14?'amber':'green')+'</div></div><div class="card"><div class="card-head"><div><h2>双维度解释</h2><p>先评估预测精度，再解读SHAP贡献</p></div></div><div class="card-body">'+['Cost_sum','Cost_car'].map((k,i)=>'<div class="insight-block"><div class="inline"><span class="tag '+(i?'green':'blue')+'">'+(i?'低碳性':'经济性')+'</span><h3 style="margin:0">'+(i?'规划环境成本':'规划总成本')+'</h3></div><div class="metric-row"><span>独立测试集 R²</span><b>'+(r?fmt(r.targets[k].test_metrics.r2,4):'等待训练')+'</b></div><p>'+(i?'环境成本含价格效应。碳价与核算关系确认后，可另行换算并解释碳排放量。':'以总成本为预测目标，查看关键输入因素及单个方案的成本贡献。')+'</p></div>').join('')+'</div></div></div>';
}
function mappingTable(list){return '<table class="mapping-table"><thead><tr><th>标准参数</th><th style="width:43%">数据列</th><th>状态</th></tr></thead><tbody>'+list.map(f=>'<tr><td>'+esc(f.label)+'<span class="field-key">'+esc(f.key)+'</span></td><td><select data-map="'+esc(f.key)+'" aria-label="'+esc(f.label)+'">'+options([{key:'',label:'未提供 / 不参与'},...S.info.columns.map(c=>({key:c,label:c}))],S.mapping[f.key])+'</select></td><td><span class="tag '+(S.mapping[f.key]?'green':'amber')+'">'+(S.mapping[f.key]?'已映射':'缺失')+'</span></td></tr>').join('')+'</tbody></table>';}
function renderData(m){
 const info=S.info;
 m.innerHTML=head('DATA WORKSPACE','数据集与规划边界','每行表示一组规划输入边界及其对应结果。支持Excel与CSV，原始文件保持不变。',button('下载字段模板','template',false,'download')+button('导入数据集','upload',true,'upload'))+
 '<div class="grid two"><div class="card pad"><h2>数据集</h2><p class="caption">选择已有案例，或上传新的输入—输出映射数据</p>'+S.datasets.map(d=>'<div class="dataset-row '+(d.id===S.ds?.id?'selected':'')+'" data-dataset="'+esc(d.id)+'" tabindex="0" role="button"><span class="file-icon">'+icon('file')+'</span><div><strong>'+esc(d.name)+'</strong><small>'+d.sheets.length+'个工作表 · '+esc(d.created_at.slice(0,10))+'</small></div><span class="tag">'+(d.example?'内置案例':'本地导入')+'</span></div>').join('')+'<div class="file-card" data-action="upload" tabindex="0" role="button">'+icon('upload')+'<strong>点击选择，或拖入文件</strong><p>.xlsx / .csv，最大32MB，仅在当前浏览器处理</p></div></div><div class="card pad"><div class="inline" style="justify-content:space-between"><h2>字段识别概况</h2><span class="tag green">自动识别，可手动调整</span></div><div class="toolbar"><label>工作表</label><select id="sheetSelect">'+options(S.ds?.sheets||[],info?.sheet)+'</select><span class="caption">表头位于原表第'+(info?.header_row||'—')+'行</span></div><div class="grid three">'+[['记录',info?.rows||0],['输入',(info?.feature_count||0)+'/14'],['输出',(info?.output_count||0)+'/10']].map(a=>'<div class="insight-block" style="margin:0"><p>'+a[0]+'</p><div class="insight-number">'+a[1]+'</div></div>').join('')+notice('缺失输入不会被填造。两项成本是解释目标，其余规划输出仅用于方案展示，均不进入输入特征。')+'</div></div>'+
 (info?'<div class="card section-gap"><div class="tabbar"><button data-datatab="mapping" class="'+(S.dataTab==='mapping'?'active':'')+'">参数字段映射</button><button data-datatab="preview" class="'+(S.dataTab==='preview'?'active':'')+'">原始数据预览</button></div>'+(S.dataTab==='mapping'?'<div class="mapping-layout card-body"><div><h3>14项规划输入参数</h3>'+mappingTable(S.catalog.features)+'</div><div><h3>10项规划输出结果</h3>'+mappingTable(S.catalog.outputs)+notice('样本编号由平台生成，并保留Excel原表行号。阶段信息不会从样本顺序或文件名推断。')+'</div></div>':'<div class="card-body"><p class="caption">前8条记录，仅展示原始值。数值显示经过取舍，计算采用原始精度。</p><div class="table-wrap"><table><thead><tr>'+info.columns.map(c=>'<th>'+esc(c)+'</th>').join('')+'</tr></thead><tbody>'+info.preview.map(row=>'<tr>'+info.columns.map(c=>'<td>'+esc(typeof row[c]==='number'?fmt(row[c],5):row[c]??'—')+'</td>').join('')+'</tr>').join('')+'</tbody></table></div></div>')+'</div>'+settingsForm():'');
}
function settingsForm(){const conf=S.result?.config||{};
 return '<div class="card section-gap"><div class="card-head"><div><h2>模型与分析设置</h2><p>两个核心目标分别训练和评估，使用Tree SHAP解释预测结果</p></div><span class="tag">同边界组合分组划分</span></div><div class="card-body"><div class="form-grid"><label><span class="field-label">树模型</span><select id="model">'+options([{key:'gradient_boosting',label:'梯度提升树（推荐）'},{key:'random_forest',label:'随机森林'},{key:'extra_trees',label:'极端随机树'}],conf.model||'gradient_boosting')+'</select></label><label><span class="field-label">独立测试集比例</span><select id="testSize">'+options([{key:'.2',label:'20%'},{key:'.25',label:'25%'},{key:'.3',label:'30%'}],String(conf.test_size||'.2').replace('0.','.'))+'</select></label><label><span class="field-label">随机种子</span><input id="seed" type="number" min="0" max="999999" value="'+(conf.seed??42)+'"></label><label><span class="field-label">成本数据单位（不作自动换算）</span><input id="costUnit" type="text" value="'+esc(conf.cost_unit||'数据原始成本单位')+'" placeholder="如 元/年、美元/日"></label><label><span class="field-label">缺失或非数值记录处理</span><select id="missingPolicy">'+options([{key:'reject',label:'停止计算，提示原表行号'},{key:'drop',label:'排除记录，并保留行号清单'}],conf.missing_policy||'reject')+'</select></label><label><span class="field-label">可选：阶段字段</span><select id="stageColumn">'+options([{key:'',label:'无阶段信息，分析当前工作表'},...S.info.columns.map(c=>({key:c,label:c}))],conf.stage_column||'')+'</select></label><label><span class="field-label">可选：阶段筛选</span><select id="stageValue">'+options([{key:"",label:"全部阶段"},...(conf.stage_value?[{key:conf.stage_value,label:conf.stage_value}]:[])],conf.stage_value||"")+'</select></label></div><div class="separator"></div><h3>碳排放换算（可选）</h3><p class="caption">核心低碳性页面始终保留环境成本解释。只有明确碳价及核算关系后，才另行训练物理排放量模型。</p><div class="form-grid"><label><span class="field-label">固定碳价（未提供碳价列时使用）</span><input id="carbonPrice" type="number" min="0" step="any" placeholder="留空表示不换算" value="'+esc(conf.fixed_carbon_price||'')+'"></label><label><span class="field-label">环境成本转为碳价币种单位的倍数</span><input id="costMultiplier" type="number" min="0" step="any" value="'+esc(conf.environment_cost_multiplier||1)+'"></label><label><span class="field-label">额外计算目标</span><select id="derive">'+options([{key:'no',label:'仅解释环境成本'},{key:'yes',label:'增加碳排放量解释'}],conf.derive_emissions?'yes':'no')+'</select></label></div><label class="check" style="margin-top:15px"><input id="carbonConfirm" type="checkbox"'+(conf.carbon_relation_confirmed?' checked':'')+'>我确认环境成本仅由“碳价×碳排放量”构成，币种与核算时期一致，碳价单位的分母为tCO₂。</label>'+notice('SHAP全局图默认使用独立测试样本。分析基准来自模型训练分布。输入参数高度相关时，贡献分配需结合采样设计解读。')+'<div class="inline" style="justify-content:space-between"><span class="caption">短时与长时储能结果参与方案对比；只有实际提供的输入参数参与训练。</span>'+button('开始双维度分析','run',true,'play')+'</div></div></div>';
}
function renderPlans(m){
 const r=S.result;m.innerHTML=head('PLANNING RESULTS','规划方案对比','按规划总成本升序展示前6个方案，并保留两类储能的功率和能量容量。',button('导出本次分析','download',false,'download'));
 if(!r){m.innerHTML+=empty('先运行一次案例分析','分析完成后，可在这里查看导入数据中的真实规划方案。');return;}
 const ids=r.rows.map((_,i)=>i).sort((a,b)=>r.targets.Cost_sum.actual[a]-r.targets.Cost_sum.actual[b]).slice(0,6);
 m.innerHTML+=notice('这里展示导入数据中的已有规划结果。模型训练和SHAP分析不会重新求解或优化储能规划。核算范围：'+esc(r.scope_label))+
 '<div class="grid three">'+ids.map((i,j)=>'<div class="card stat"><div class="stat-label">'+esc(r.rows[i].id)+(j===0?'<span class="tag blue">所选数据中成本最低</span>':'<span class="tag">'+(r.rows[i].split==='test'?'测试样本':'训练样本')+'</span>')+'</div><div class="stat-value '+(j===0?'blue':'')+'">'+compact(r.targets.Cost_sum.actual[i])+'</div><div class="stat-note">规划总成本 · '+esc(r.targets.Cost_sum.unit)+' · 原表第'+r.rows[i].source_row+'行</div></div>').join('')+'</div>'+
 '<div class="grid two section-gap"><div class="card"><div class="card-head"><h2>短时储能配置</h2><span class="tag blue">功率 / 能量容量</span></div>'+chart('short-plan','medium')+'<p class="chart-note">功率与能量分开标轴，保持原始数据单位。</p></div><div class="card"><div class="card-head"><h2>长时储能配置</h2><span class="tag green">充电 / 放电 / 能量</span></div>'+chart('long-plan','medium')+'<p class="chart-note">长时储能充电功率、放电功率和能量容量分别展示。</p></div></div>'+
 '<div class="card section-gap"><div class="card-head"><div><h2>规划成本对比</h2><p>两项成本量级不同，左右轴分别标注。环境成本不能重复加到总成本上。</p></div></div>'+chart('cost-plan','short')+'</div>'+
 '<div class="card section-gap"><div class="card-head"><h2>前6个方案完整结果</h2></div><div class="card-body table-wrap"><table><thead><tr><th>方案 / 原表行号</th>'+S.catalog.outputs.map(f=>'<th>'+esc(f.label)+'</th>').join('')+'</tr></thead><tbody>'+ids.map(i=>'<tr><td>'+r.rows[i].id+' / '+r.rows[i].source_row+'</td>'+S.catalog.outputs.map(f=>'<td>'+fmt(r.rows[i].outputs[f.key])+'</td>').join('')+'</tr>').join('')+'</tbody></table></div></div>';
 const cats=ids.map(i=>r.rows[i].id),vals=k=>ids.map(i=>r.rows[i].outputs[k]??null);
 const common=pbase({margin:{l:70,r:35,t:45,b:45},showlegend:true,legend:{orientation:'h',y:1.12,x:0},barmode:'group',yaxis:{domain:[.58,1],title:'能量 / 原始单位',gridcolor:'#edf1f7'},xaxis:{domain:[0,1],anchor:'y'},yaxis2:{domain:[0,.35],title:'功率 / 原始单位',gridcolor:'#edf1f7'},xaxis2:{domain:[0,1],anchor:'y2'}});
 plot('short-plan',[{type:'bar',name:'能量容量',x:cats,y:vals('SDES_e'),marker:{color:'#2563df'}},{type:'bar',name:'规划功率',x:cats,y:vals('SDES_p'),xaxis:'x2',yaxis:'y2',marker:{color:'#8cafed'}}],common);
 plot('long-plan',[{type:'bar',name:'能量容量',x:cats,y:vals('LDES_e'),marker:{color:'#16968a'}},{type:'bar',name:'充电功率',x:cats,y:vals('LDES_ch'),xaxis:'x2',yaxis:'y2',marker:{color:'#4fc2bc'}},{type:'bar',name:'放电功率',x:cats,y:vals('LDES_dis'),xaxis:'x2',yaxis:'y2',marker:{color:'#167a70'}}],common);
 plot('cost-plan',[{type:'bar',name:'规划总成本（左轴）',x:cats,y:vals('Cost_sum'),marker:{color:'#356ae1'}},{type:'scatter',mode:'lines+markers',name:'环境成本（右轴）',x:cats,y:vals('Cost_car'),yaxis:'y2',line:{color:'#179487',width:2}}],{margin:{l:90,r:95,t:40,b:45},legend:{orientation:'h',y:1.2},yaxis:{title:'总成本 / '+r.targets.Cost_sum.unit,gridcolor:'#edf1f7'},yaxis2:{title:'环境成本 / '+r.targets.Cost_car.unit,overlaying:'y',side:'right',showgrid:false},xaxis:{tickfont:{size:11}}});
}
function renderAnalysis(m){
 const r=S.result,carbon=S.page==='carbon';m.innerHTML=head(carbon?'LOW-CARBON VALUE':'ECONOMIC VALUE',carbon?'低碳性可解释分析':'经济性可解释分析',carbon?'以规划环境成本为核心目标，区分价格效应与物理排放。':'识别规划输入对总成本预测的影响，连接全局规律与单个方案。',button('下载分析数据','download',false,'download'));
 if(!r){m.innerHTML+=empty('尚无可解释分析结果','选择输入—输出数据集，训练模型并计算真实SHAP贡献后即可查看。');return;}
 const key=activeTarget(),t=r.targets[key],sc=targetScale(key),order=rank(key),test=t.test_metrics;
 if(S.dep>=r.features.length)S.dep=order[0];if(S.color>=r.features.length)S.color=0;
 const issue=carbon?notice(esc(r.emission_note),'amber'):notice(esc(r.explanation_boundary));
 m.innerHTML+=issue+'<div class="toolbar"><span class="tag '+(carbon?'green':'blue')+'">'+esc(t.label)+'</span>'+(carbon?'<div class="target-tabs"><button data-carbon="Cost_car" class="'+(key==='Cost_car'?'active':'')+'">环境成本</button><button data-carbon="Emissions" '+(!r.targets.Emissions?'disabled title="请在数据设置中确认碳价和核算关系后重新分析"':'')+' class="'+(key==='Emissions'?'active':'')+'">碳排放量'+(!r.targets.Emissions?'（未换算）':'')+'</button></div>':'')+'<label>全局解释样本</label><select id="cohort">'+options([{key:'test',label:'独立测试样本（推荐）'},{key:'all',label:'全部样本（含训练样本）'}],S.cohort)+'</select><span class="caption">'+esc(r.sheet)+' · '+indices().length+'条样本 · '+esc(r.method)+'</span></div>'+
 '<div class="grid four">'+stat('独立测试集 R²',fmt(test.r2,4),'训练集 R² '+fmt(t.train_metrics.r2,4),test.r2>=.8?'blue':'','chart')+stat('独立测试集 MAE',compact(test.mae),esc(t.unit),'','layers')+stat('解释基准 E[f(X)]',compact(t.base_value),'模型训练分布对应的基准预测','','database')+stat('SHAP加和最大误差',Number(t.additivity_max_error).toExponential(2),'基准值＋贡献合计＝模型预测','teal','check')+'</div>'+
 '<div class="grid analysis section-gap"><div class="card"><div class="card-head"><div><h2>全局可解释分析</h2><p>解释当前样本范围内的总体影响规律</p></div><span class="tag">'+r.features.length+'项实际变化输入</span></div><div class="tabbar">'+[['bar','重要性排序'],['beeswarm','蜂群分布'],['dependence','依赖关系'],['heatmap','贡献热力图']].map(a=>'<button data-global="'+a[0]+'" class="'+(S.globalTab===a[0]?'active':'')+'">'+a[1]+'</button>').join('')+'</div>'+
 (S.globalTab==='dependence'?'<div class="chart-control"><label>分析因素</label><select id="depFeature">'+options(r.features.map((f,j)=>({key:j,label:f.label})),S.dep)+'</select><label>着色因素</label><select id="colorFeature">'+options(r.features.map((f,j)=>({key:j,label:f.label})),S.color)+'</select></div>':'')+
 chart('global-chart',r.features.length>9?'tall':'')+'<p id="global-note" class="chart-note"></p></div><aside><div class="card pad"><h3>当前结果解读</h3><span class="tag '+(test.r2>=.8?'green':'amber')+'">预测表现：'+esc(t.quality)+'</span><div class="separator"></div><div class="insight-block"><h3>首要关联因素</h3><p>'+esc(r.features[order[0]].label)+'</p><div class="insight-number">'+fmt((S.cohort==='test'?t.importance_test:t.importance_all)[order[0]]/sc.scale,3)+'</div><p>平均绝对贡献 / '+esc(sc.unit)+'</p></div><p class="small-text" style="line-height:1.9">绝对SHAP值衡量影响强度，不代表方向。正值推高当前目标预测，负值降低预测。</p><div class="metric-row"><span>解释范围</span><b>'+indices().length+'条</b></div><div class="metric-row"><span>缺失输入</span><b>'+r.missing_features.length+'项</b></div><div class="metric-row"><span>固定输入</span><b>'+r.fixed_features.length+'项</b></div></div><div class="card section-gap"><div class="card-head"><h2>预测与实际值</h2></div>'+chart('fit-chart','short')+'<p class="chart-note">仅使用独立测试集，虚线表示理想预测。</p></div></aside></div>'+
 '<div class="card section-gap"><div class="card-head"><div><h2>局部方案解释</h2><p>解释所选方案的模型预测，实际值与预测值分别呈现</p></div><div class="inline"><label class="caption">选择方案</label><select id="sampleSelect" aria-label="选择局部解释方案">'+options(r.rows.map((row,i)=>({key:i,label:row.id+' · 原表'+row.source_row+'行 · '+(row.split==='test'?'测试':'训练')})),S.sample)+'</select></div></div><div class="sample-info" id="sample-info"></div><div class="tabbar">'+[['waterfall','瀑布图'],['force','力图'],['decision','决策路径']].map(a=>'<button data-local="'+a[0]+'" class="'+(S.localTab===a[0]?'active':'')+'">'+a[1]+'</button>').join('')+'</div><div id="local-holder">'+(S.localTab==='force'?'<iframe id="forceFrame" title="SHAP局部力图" style="width:100%;height:290px;border:0" src="'+forceUrl(r.id,key,S.sample)+'"></iframe>':chart('local-chart','medium'))+'</div><p class="chart-note">'+(S.localTab==='force'?'使用SHAP原生交互力图，点击图形可查看详细贡献。':S.localTab==='decision'?'按全局重要性顺序累加贡献，比较所选方案及测试集中其他方案。':'从基准预测出发，逐项累加贡献得到最终预测。未单独展示的贡献合并为“其他因素”。')+'</p></div>'+
 (r.warnings.length?'<div class="card pad section-gap"><h3>本次分析的适用范围</h3><ul class="list-note">'+r.warnings.map(w=>'<li>'+esc(w)+'</li>').join('')+'</ul></div>':'');
 drawGlobal();drawFit();drawLocal();
}
function drawGlobal(){
 const r=S.result,key=activeTarget(),t=r.targets[key],sc=targetScale(key),ix=indices(),order=rank(key),features=r.features,labels=order.map(j=>features[j].label),note=$('#global-note');
 const im=S.cohort==='test'?t.importance_test:t.importance_all;
 if(S.globalTab==='bar'){let rev=[...order].reverse();plot('global-chart',[{type:'bar',orientation:'h',x:rev.map(j=>im[j]/sc.scale),y:rev.map(j=>features[j].label),marker:{color:S.page==='carbon'?'#15988a':'#326be1'},text:rev.map(j=>fmt(im[j]/sc.scale,3)),textposition:'outside',hovertemplate:'%{y}<br>平均绝对SHAP值 %{x:.4g}<extra></extra>'}],{xaxis:{title:'mean(|SHAP|) / '+sc.unit,gridcolor:'#edf1f7',zeroline:false},yaxis:{showgrid:false},margin:{l:260,r:72,t:22,b:65}});note.textContent='按平均绝对SHAP值排序。数值使用同一目标单位，统计覆盖当前选定的全部样本。';}
 if(S.globalTab==='beeswarm'){
  let keep=ix.filter((_,i)=>i%Math.max(1,Math.ceil(ix.length/600))===0),traces=[];
  order.forEach((j,row)=>{let vs=keep.map(i=>r.rows[i].features[features[j].key]),min=Math.min(...vs),max=Math.max(...vs),bins={};let width=Math.max(...keep.map(i=>Math.abs(t.shap[i][j])))/32||1;let ys=keep.map(i=>{let b=Math.round(t.shap[i][j]/width);let k=bins[b]||0;bins[b]=k+1;return row+(k%2===0?1:-1)*Math.ceil(k/2)*.034;});traces.push({type:'scatter',mode:'markers',x:keep.map(i=>t.shap[i][j]/sc.scale),y:ys,text:keep.map(i=>r.rows[i].id+'<br>'+esc(features[j].label)+' = '+fmt(r.rows[i].features[features[j].key],5)),marker:{size:5,opacity:.8,color:vs.map(v=>(v-min)/(max-min||1)),cmin:0,cmax:1,colorscale:[[0,'#2878c8'],[.5,'#c8b4d5'],[1,'#e85387']],showscale:row===0,colorbar:{title:'特征值',thickness:9,len:.75,tickvals:[0,1],ticktext:['低','高']}},showlegend:false,hovertemplate:'%{text}<br>SHAP %{x:.4g}<extra></extra>'});});
  plot('global-chart',traces,{margin:{l:260,r:65,t:22,b:60},xaxis:{title:'SHAP值 / '+sc.unit,gridcolor:'#edf1f7',zeroline:true,zerolinecolor:'#9eaec5'},yaxis:{tickvals:order.map((_,i)=>i),ticktext:labels,autorange:'reversed',showgrid:false}});
  note.textContent='每个点是一条数据样本。横向位置表示SHAP贡献，颜色表示该因素的相对高低。图形最多显示600条样本，统计仍使用选定样本全集。';
 }
 if(S.globalTab==='dependence'){
  let j=Number(S.dep),c=Number(S.color),f=features[j],col=features[c];plot('global-chart',[{type:'scatter',mode:'markers',x:ix.map(i=>r.rows[i].features[f.key]),y:ix.map(i=>t.shap[i][j]/sc.scale),text:ix.map(i=>r.rows[i].id),marker:{size:6,opacity:.75,color:ix.map(i=>r.rows[i].features[col.key]),colorscale:[[0,'#297fc3'],[.5,'#cab7da'],[1,'#e75886']],showscale:true,colorbar:{title:{text:col.label.replace('单位','<br>单位')},thickness:9,len:.65}},hovertemplate:'%{text}<br>输入 %{x:.5g}<br>SHAP %{y:.4g}<extra></extra>'}],{margin:{l:90,r:160,t:24,b:70},xaxis:{title:f.label+' / 原始输入单位',gridcolor:'#edf1f7'},yaxis:{title:'SHAP值 / '+sc.unit,gridcolor:'#edf1f7',zeroline:true}});
  note.textContent='横轴为输入值，纵轴为其对当前目标的SHAP贡献。该图展示模型关联，不是参数干预后的因果效应。';
 }
 if(S.globalTab==='heatmap'){
  let sorted=[...ix].sort((a,b)=>t.predicted[a]-t.predicted[b]),keep=sorted.filter((_,i)=>i%Math.max(1,Math.ceil(sorted.length/200))===0);
  plot('global-chart',[{type:'heatmap',x:keep.map(i=>r.rows[i].id),y:labels,z:order.map(j=>keep.map(i=>t.shap[i][j]/sc.scale)),colorscale:[[0,'#2f78c0'],[.5,'#f8f9fc'],[1,'#df597e']],zmid:0,colorbar:{title:'SHAP',thickness:10},hovertemplate:'%{x}<br>%{y}<br>贡献 %{z:.4g}<extra></extra>'}],{margin:{l:260,r:70,t:24,b:60},xaxis:{title:'按预测值升序排列的样本',showticklabels:false},yaxis:{autorange:'reversed',showgrid:false}});
  note.textContent='观察不同样本的贡献模式。最多显示200条等间隔抽样记录，颜色使用同一SHAP量纲。';
 }
}
function drawFit(){let r=S.result,key=activeTarget(),t=r.targets[key],sc=targetScale(key),ix=r.test_indices,lo=Math.min(...ix.map(i=>t.actual[i]))/sc.scale,hi=Math.max(...ix.map(i=>t.actual[i]))/sc.scale;
 plot('fit-chart',[{type:'scatter',mode:'markers',x:ix.map(i=>t.actual[i]/sc.scale),y:ix.map(i=>t.predicted[i]/sc.scale),marker:{size:4,color:'#3c83c8',opacity:.6},text:ix.map(i=>r.rows[i].id),hovertemplate:'%{text}<br>实际 %{x:.4g}<br>预测 %{y:.4g}<extra></extra>'},{type:'scatter',mode:'lines',x:[lo,hi],y:[lo,hi],line:{color:'#c29575',width:1,dash:'dash'},hoverinfo:'skip'}],{margin:{l:55,r:20,t:15,b:45},showlegend:false,xaxis:{title:'实际值',gridcolor:'#edf1f7',tickfont:{size:9}},yaxis:{title:'预测值',gridcolor:'#edf1f7',tickfont:{size:9}}});
}
function drawLocal(){
 const r=S.result,key=activeTarget(),t=r.targets[key],i=Number(S.sample),row=r.rows[i],sc=targetScale(key),pred=t.predicted[i],actual=t.actual[i];
 $('#sample-info').innerHTML='方案 <b>'+row.id+'</b> · 原表第 <b>'+row.source_row+'</b> 行 · '+(row.split==='test'?'独立测试样本':'训练样本')+'　实际值 <b>'+fmt(actual)+'</b>　模型预测 <b>'+fmt(pred)+'</b>　预测偏差 <b>'+fmt(pred-actual)+'</b> '+esc(t.unit);
 if(S.localTab==='force')return;
 if(S.localTab==='waterfall'){
  const order=t.shap[i].map((v,j)=>({v,j})).sort((a,b)=>Math.abs(b.v)-Math.abs(a.v));let main=order.slice(0,8),other=order.slice(8).reduce((s,q)=>s+q.v,0);
  let labs=['基准预测',...main.map(q=>(typeof shortLabel==='function'?shortLabel(r.features[q.j]).replace('储能','储能<br>'):r.features[q.j].label)+'<br><span style="color:#8a9bb1">'+fmt(row.features[r.features[q.j].key],4)+'</span>')],vals=[t.base_value,...main.map(q=>q.v)],measures=['absolute',...main.map(()=>'relative')];
  if(order.length>8){labs.push('其他因素');vals.push(other);measures.push('relative');}labs.push('最终预测');vals.push(0);measures.push('total');
  let text=[fmt(t.base_value/sc.scale,3),...main.map(q=>(q.v>=0?'+':'')+fmt(q.v/sc.scale,3))];if(order.length>8)text.push((other>=0?'+':'')+fmt(other/sc.scale,3));text.push(fmt(pred/sc.scale,3));
  let level=0,levels=[0];vals.forEach((v,j)=>{if(measures[j]==='absolute')level=v;else if(measures[j]==='relative')level+=v;levels.push(level/sc.scale);});const low=Math.min(...levels),high=Math.max(...levels),span=high-low||1;
  plot('local-chart',[{type:'waterfall',x:labs,y:vals.map(v=>v/sc.scale),measure:measures,text,textposition:'outside',cliponaxis:false,connector:{line:{color:'#b7c6dc',width:1,dash:'dot'}},increasing:{marker:{color:'#e85c89'}},decreasing:{marker:{color:'#219e9c'}},totals:{marker:{color:'#326be1'}},hovertemplate:'%{x}<br>贡献/值 %{y:.5g}<extra></extra>'}],{margin:{l:85,r:35,t:45,b:105},showlegend:false,yaxis:{title:t.label+' / '+sc.unit,gridcolor:'#edf1f7',range:[low-(low<0?span*.06:0),high+span*.18]},xaxis:{tickfont:{size:10},automargin:true}});
 }
 if(S.localTab==='decision'){
  let order=[...rank(key)].reverse(),ids=[i,...r.test_indices.filter(n=>n!==i).slice(0,9)];
  let traces=ids.map((idx,k)=>{let total=t.base_value,xx=[total/sc.scale];order.forEach(j=>{total+=t.shap[idx][j];xx.push(total/sc.scale);});return {type:'scatter',mode:'lines+markers',x:xx,y:xx.map((_,a)=>a),name:r.rows[idx].id,line:{color:k===0?'#255fce':['#afd6d0','#d9b9ca','#b3c8e9'][k%3],width:k===0?3:1},marker:{size:k===0?5:2},opacity:k===0?1:.65,hovertemplate:r.rows[idx].id+'<br>累计预测 %{x:.5g}<extra></extra>'};});
  plot('local-chart',traces,{margin:{l:270,r:70,t:25,b:50},xaxis:{title:'累计预测 / '+sc.unit,gridcolor:'#edf1f7'},yaxis:{tickvals:[0,...order.map((_,j)=>j+1)],ticktext:['基准预测',...order.map(j=>r.features[j].label)],gridcolor:'#f2f5fa'},legend:{font:{size:10},x:1.01,y:1}});
 }
}
function renderReports(m){
 const r=S.result,j=S.job;
 m.innerHTML=head('RUNS & EVIDENCE','运行记录与报告','保存数据版本、模型配置、评估结果与逐样本贡献，让每一次分析可以复核。',button('刷新记录','refresh',false,'clock'));
 if(j)m.innerHTML+='<div class="card pad"><div class="inline" style="justify-content:space-between"><h2>'+({queued:'等待运行',running:'正在分析',done:'分析已完成',error:'分析未完成'}[j.status]||j.status)+'</h2><span class="tag '+(j.status==='error'?'amber':'blue')+'">'+fmt(j.progress,0)+'%</span></div><div class="progress-wrap"><div class="progress-bar" style="width:'+j.progress+'%"></div></div>'+(j.error?notice(esc(j.error),'amber'):'')+'<div>'+j.logs.map(l=>'<div class="log-item"><b>'+esc(l.title)+'</b><time>'+esc(l.time)+'</time><p>'+esc(l.detail)+'</p></div>').join('')+'</div></div>';
 m.innerHTML+='<div class="grid analysis section-gap"><div class="card"><div class="card-head"><div><h2>已保存的分析</h2><p>只列出成功完成并保存的记录</p></div><span class="tag">'+S.runs.length+'次</span></div><div class="record-list">'+(S.runs.length?S.runs.map(v=>'<div class="record-item"><span class="file-icon">'+icon('file')+'</span><div class="record-main"><b>'+esc(v.dataset_name)+'</b><p>'+esc(v.sheet)+' · '+esc(localTime(v.created_at))+' · '+fmt(v.duration_seconds,1)+'秒</p></div><button class="small" data-loadrun="'+v.id+'">'+(r?.id===v.id?'当前记录':'打开结果')+'</button></div>').join(''):'<div class="empty"><p>暂无记录。请先导入数据并运行分析。</p></div>')+'</div></div><div class="card pad"><h2>报告与分析数据</h2><p class="caption">当前记录：'+esc(r?.id||'未选择')+'</p><div class="report-actions"><button data-action="report" '+(!r?'disabled':'')+'>'+icon('file')+'下载离线HTML报告</button><button data-action="download" '+(!r?'disabled':'')+'>'+icon('download')+'下载完整分析包 ZIP</button><button data-action="template">'+icon('database')+'下载24字段CSV模板</button></div><p class="caption section-gap">分析包包含报告、完整结果JSON、SHAP贡献矩阵和关键因素排序CSV。</p></div></div>';
 if(r)m.innerHTML+='<div class="card pad section-gap"><h2>当前分析追溯信息</h2><div class="grid two section-gap"><div>'+[['数据集',r.dataset_name],['工作表',r.sheet],['模型',r.config.model],['解释方法',r.method],['训练 / 测试',r.train_indices.length+' / '+r.test_indices.length]].map(a=>'<div class="metric-row"><span>'+a[0]+'</span><b>'+esc(a[1])+'</b></div>').join('')+'</div><div>'+[['随机种子',r.config.seed],['SHAP算法',r.versions.shap],['模型计算引擎',r.versions.sklearn],['排除缺失记录',r.invalid_rows.length+'条'],['特征数量',r.features.length+'项变化输入']].map(a=>'<div class="metric-row"><span>'+a[0]+'</span><b>'+esc(a[1])+'</b></div>').join('')+'</div></div><p class="caption section-gap" style="word-break:break-all">源数据 SHA256：'+esc(r.source_sha256)+'</p>'+notice(esc(r.split_method)+'。'+esc(r.explanation_boundary))+'</div>';
}
function readConfig(){let old=S.result?.config||{};const val=(id,fallback)=>document.getElementById(id)?.value??fallback;return {dataset_id:S.ds.id,sheet:S.info.sheet,mapping:S.mapping,model:val('model',old.model||'gradient_boosting'),test_size:Number(val('testSize',old.test_size||.2)),seed:Number(val('seed',old.seed??42)),cost_unit:val('costUnit',old.cost_unit||'数据原始成本单位'),missing_policy:val('missingPolicy','reject'),stage_column:val('stageColumn',''),stage_value:val('stageValue',''),derive_emissions:val('derive','no')==='yes',fixed_carbon_price:val('carbonPrice',''),environment_cost_multiplier:Number(val('costMultiplier',1)),carbon_relation_confirmed:$('#carbonConfirm')?.checked||false};}
async function run(){if(S.job&&['running','queued'].includes(S.job.status)){location.hash='reports';return;}if(!S.ds||!S.info)throw Error('请先选择数据集。');const config=readConfig();const d=await post('/api/runs',config);S.job={id:d.id,status:'queued',progress:0,logs:[]};location.hash='reports';render();pollJob(d.id);}
async function pollJob(id){try{const j=await api('/api/jobs/'+id);S.job=j;if(S.page==='reports')render();if(j.status==='done'){await loadResult(id);S.runs=await api('/api/runs');render();toast('双维度SHAP分析已完成，可查看经济性与低碳性结果。');}else if(j.status==='error'){toast(j.error);}else setTimeout(()=>pollJob(id),900);}catch(e){toast(e.message);}}
async function doAction(action){switch(action){case'goto-data':location.hash='data';break;case'goto-economy':location.hash='economy';break;case'upload':$('#uploadFile').click();break;case'template':window.location.href='/api/template';break;case'run':await run();break;case'download':if(!S.result)throw Error('请先完成一次分析。');window.location.href='/api/runs/'+S.result.id+'/download';break;case'report':if(!S.result)throw Error('请先完成一次分析。');window.location.href='/api/runs/'+S.result.id+'/report';break;case'refresh':S.runs=await api('/api/runs');render();break;}}
document.addEventListener('click',async e=>{try{
 let a=e.target.closest('[data-action]');if(a){await doAction(a.dataset.action);return;}
 let ds=e.target.closest('[data-dataset]');if(ds){await selectDataset(ds.dataset.dataset);if(S.result?.dataset_id!==S.ds.id)S.result=null;render();return;}
 let tab=e.target.closest('[data-datatab]');if(tab){S.dataTab=tab.dataset.datatab;render();return;}
 tab=e.target.closest('[data-global]');if(tab){S.globalTab=tab.dataset.global;render();return;}
 tab=e.target.closest('[data-local]');if(tab){S.localTab=tab.dataset.local;render();return;}
 tab=e.target.closest('[data-carbon]');if(tab&&!tab.disabled){S.carbonTarget=tab.dataset.carbon;S.dep=rank(S.carbonTarget)[0];render();return;}
 let rec=e.target.closest('[data-loadrun]');if(rec){await loadResult(rec.dataset.loadrun);toast('已打开分析记录。');location.hash='economy';render();}
 }catch(error){toast(error.message);}});
document.addEventListener('change',async e=>{try{const x=e.target;
 if(x.dataset.map){S.mapping[x.dataset.map]=x.value;let tag=x.closest('tr').querySelector('.tag');tag.textContent=x.value?'已映射':'缺失';tag.className='tag '+(x.value?'green':'amber');return;}
 if(x.id==='sheetSelect'){await selectDataset(S.ds.id,x.value);if(S.result?.sheet!==x.value)S.result=null;render();}
 if(x.id==='cohort'){S.cohort=x.value;render();}
 if(x.id==='depFeature'){S.dep=Number(x.value);drawGlobal();}
 if(x.id==='colorFeature'){S.color=Number(x.value);drawGlobal();}
 if(x.id==='sampleSelect'){S.sample=Number(x.value);if(S.localTab==='force')$('#forceFrame').src=forceUrl(S.result.id,activeTarget(),S.sample);drawLocal();}
 if(x.id==='stageColumn'){let vv=await api('/api/datasets/'+S.ds.id+'/stages?sheet='+encodeURIComponent(S.info.sheet)+'&column='+encodeURIComponent(x.value));$('#stageValue').innerHTML=options([{key:'',label:'全部阶段'},...vv],'');}
 if(x.id==='uploadFile'&&x.files[0])await upload(x.files[0]);
 }catch(error){toast(error.message);}});
async function upload(file){toast('正在读取并校验文件…');let form=new FormData();form.append('file',file);let ds=await api('/api/datasets/upload',{method:'POST',body:form});S.datasets=await api('/api/datasets');await selectDataset(ds.id);S.result=null;S.dataTab='mapping';location.hash='data';render();toast('已导入 '+file.name);}
document.addEventListener('dragover',e=>{if(e.target.closest('.file-card')){e.preventDefault();}});
document.addEventListener('drop',async e=>{if(e.target.closest('.file-card')){e.preventDefault();try{if(e.dataTransfer.files[0])await upload(e.dataTransfer.files[0]);}catch(err){toast(err.message);}}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role=button]')){e.preventDefault();e.target.click();}});
window.addEventListener('hashchange',()=>{window.scrollTo(0,0);render();});
window.addEventListener('resize',()=>{clearTimeout(resizeCharts.t);resizeCharts.t=setTimeout(resizeCharts,120);});
async function init(){try{$('#main').innerHTML='<div class="loading">正在准备独立分析工作区</div>';[S.catalog,S.datasets,S.runs]=await Promise.all([api('/api/catalog'),api('/api/datasets'),api('/api/runs')]);if(!S.datasets.length){await post('/api/datasets/example',{});S.datasets=await api('/api/datasets');}let dsid=workspacePrefs.getItem('public-storage-shap-dataset');await selectDataset(S.datasets.some(d=>d.id===dsid)?dsid:S.datasets[0].id);let rid=workspacePrefs.getItem('public-storage-shap-run')||S.runs[0]?.id;if(rid&&S.runs.some(r=>r.id===rid))await loadResult(rid);await render();}catch(err){$('#main').innerHTML='<div class="card empty"><h3>浏览器工作区尚未就绪</h3><p>'+esc(err.message)+'</p><p>请刷新网页，并检查浏览器是否允许本网站保存数据。</p></div>';}}
init();

